H.background();
const cx = H.W / 2, cy = H.H / 2 + 20;
const R = 170;
let n = Math.round(P.n);
if (n < 3) n = 3;
if (n > 16) n = 16;
const pts = [];
const rot = -Math.PI / 2 + 0.15 * Math.sin(t * 0.5);
for (let i = 0; i < n; i++) {
  const ang = rot + i * 2 * Math.PI / n;
  pts.push([cx + R * Math.cos(ang), cy + R * Math.sin(ang)]);
}
H.path(pts, { color: H.colors.accent, width: 3, close: true, fill: H.colors.accent });
const apothem = R * Math.cos(Math.PI / n);
const side = 2 * R * Math.sin(Math.PI / n);
const perim = n * side;
const area = 0.5 * apothem * perim;
const k = Math.floor((t * 0.4) % n);
const p1 = pts[k], p2 = pts[(k + 1) % n];
const mx = (p1[0] + p2[0]) / 2, my = (p1[1] + p2[1]) / 2;
H.line(p1[0], p1[1], p2[0], p2[1], { color: H.colors.warn, width: 4 });
H.line(cx, cy, mx, my, { color: H.colors.accent2, width: 3, dash: [6, 4] });
H.circle(cx, cy, 4, { fill: H.colors.ink });
H.text("apothem a", (cx + mx) / 2 + 6, (cy + my) / 2 - 6, { color: H.colors.accent2, size: 12 });
H.text("side s", mx + 6, my + 6, { color: H.colors.warn, size: 12 });
H.text("Regular polygon area = (1/2) a P", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("n = " + n + " sides   a = " + apothem.toFixed(1) + "   P = n s = " + perim.toFixed(1), 24, 52, { color: H.colors.sub, size: 13 });
H.text("Area = (1/2)(" + apothem.toFixed(1) + ")(" + perim.toFixed(1) + ") = " + area.toFixed(0) + " px^2", 24, 72, { color: H.colors.accent2, size: 13 });
